// Compares every lower-limb nerve with bony and arterial landmarks and with the leg and foot bones, and writes docs/lower-limb-nerves.md.
//   node scripts/audit-lower-nerves.mjs            prints the table
//   node scripts/audit-lower-nerves.mjs --write    rewrites docs/lower-limb-nerves.md
import fs from 'node:fs';
import {loadWorld} from './lib/paokao-world.mjs';
import {measure} from './lib/lower-limb-nerve-metrics.mjs';

const {rows, inside} = measure(loadWorld({paokao: true}));
const lines = ['# Lower-limb nerves against landmarks and bones', '',
  'Generated by `node scripts/audit-lower-nerves.mjs --write` from the meshes the viewer draws (millimetres; right and left measured separately). A row marked **required** is enforced by `npm run check` (`scripts/check-nerve-course.mjs`); the others are reported only.', '',
  '## Landmark rules', '', '| Nerve | Side | Rule | Measured | Result |', '| --- | --- | --- | --- | --- |'];
for (const r of rows) lines.push(`| ${r.nerve} | ${r.side} | ${r.rule}${r.required ? ' (**required**)' : ''} | ${r.value} ${r.unit} | ${r.ok ? 'pass' : 'FAIL' + (r.note ? ' — ' + r.note : '')} |`);
lines.push('', '## Nerve meshes with vertices inside a leg or foot bone (after the clearance step)', '', '| Mesh | Vertices inside | Of |', '| --- | --- | --- |');
for (const r of inside.filter(r => r.inside).sort((a, b) => b.inside / b.total - a.inside / a.total)) lines.push(`| ${r.name} | ${r.inside} | ${r.total} |`);
if (!inside.some(r => r.inside)) lines.push('| (none) | 0 | |');
const text = lines.join('\n') + '\n';
if (process.argv.includes('--write')) { fs.writeFileSync(new URL('../docs/lower-limb-nerves.md', import.meta.url), text); console.log('docs/lower-limb-nerves.md written:', rows.length, 'rules,', rows.filter(r => !r.ok).length, 'failing'); }
else console.log(text);
